# ---------------------------------------------------------------- CH 12
dict(id=12, title='CHIEF MINISTER AND STATE EXECUTIVE', toc='Chief Minister and Council of Ministers', icon='landmark', **PART,
     pyq='Prelims 2016', prio='L',
     simple='The Governor reigns, the CM rules: how the CM is appointed (hung Assembly, non-members), oath, term and powers, the Council of Ministers (ranks, 91st Am. cap, responsibility), Cabinet and Chief Secretary.',
     nodes=[
  fl(['CM appointed (Art 164)', 'Oaths: office and secrecy', 'Pleasure = Assembly confidence', 'Council: 4 ranks', '91st Am.: 15% and 12', 'Chief Secretary'], 'At a glance: the route', 3),
  bx('bl', '<b>Governor</b> = nominal, <b>de jure</b>, constitutional head. <b>CM</b> = real, <b>de facto</b> head, like the PM at the Union. Executive power is described as resting with the Council, but the CM plays the central, commanding role.'),
  bx('ye', '<b>Source conflict:</b> this chapter says executive power is “vested in the Council of Ministers”; the Governor chapter says Art 154 vests it in the Governor, exercised through the Council. Rule: formally Governor (Art 154), in practice Council under the CM.'),
  sec('APPOINTMENT OF THE CM (ART 164)', 'b'),
  tb(['Situation', 'Practice'],
     ['<b>1 Normal</b>', 'one party has absolute majority: Governor <b>must appoint its leader</b>; purely formal'],
     ['<b>2 Hung Assembly</b>', 'limited personal discretion: usually invites largest party or post-poll coalition; appointee proves majority on floor, generally <b>within a month</b> or period Governor specifies; legitimacy from legislative confidence'],
     ['<b>3 Death of sitting CM</b>', 'no immediate successor: Governor may use individual judgment; conventionally ruling party elects new leader quickly, whom he must appoint'],
     ['<b>4 Non-legislator (Art 164(4))</b>', 'may be appointed but must be elected within <b>6 months</b> or ceases to hold office automatically']),
  mn('N-H-D-N', 'Four situations: <b>N</b>ormal majority, <b>H</b>ung Assembly, <b>D</b>eath of CM, <b>N</b>on-member: “<b>N</b>o <b>H</b>ousehold <b>D</b>isputes <b>N</b>ow”.'),
  bx('pk', '<b>Six-month rule:</b> non-member CM or minister gets <b>6 months</b> to get elected, else out (Arts 164(4) and 164(1)(f) in handout). <b>Proof of majority:</b> Constitution does not require it before appointment; Governor appoints first, asks him to prove majority within a reasonable time; final authority = Legislature.'),
  t('<b>B.R. Kapoor case (2001)</b>', '<b>Qualification:</b> one not qualified to contest cannot use <b>Art 75(5)</b> and <b>Art 164(4)</b>', '<b>No arbitrary appointment:</b> may appoint competent person who lost an election; person unable to contest due to other constitutional commitments; experts', '<b>No repeats:</b> no repeat appointment after the 6 months expire', w=24),
  fl(['Election: no clear majority', 'Governor invites largest party or post-poll coalition leader', 'Appoints him CM', 'Floor test, about a month', 'Legislature decides'], 'Hung Assembly path', 5),
  bx('gr', '<b>Sarkaria on choosing a CM:</b> Governor’s task is to see a government is formed, not one whose policies he likes; single party with absolute majority: its leader asked automatically. <b>Order if no majority:</b> (1) pre-poll alliance, (2) largest single party with support of others incl. independents, (3) post-poll coalition with all partners in government, (4) post-poll alliance with some partners supporting from outside. A CM not leading an absolute-majority party should seek confidence vote within <b>30 days</b>; if majority contested, test it on the House floor. <b>S.R. Bommai (1994):</b> CM cannot be dismissed while he has majority support; many Governors violated this by dismissing without floor test.'),
  bx('pk', '<b>Membership:</b> CM can sit in either House; convention picks from Assembly, but Council members (Uttar Pradesh and Bihar named) have been CMs.'),
  sec('OATH, TERM AND SALARY', 'r'),
  tb(['Oath', 'Content'],
     ['<b>Office (Art 164(3))</b>', 'bear true faith and allegiance to Constitution; uphold sovereignty and integrity of India; discharge duties faithfully and conscientiously; do right to all without fear or favour, affection or ill will'],
     ['<b>Secrecy</b>', 'not to communicate matters known as Minister to unauthorised person, except for due discharge of duties']),
  mn('B-U-F-D', 'CM’s oath of office: <b>B</b>ear true faith · <b>U</b>phold sovereignty · <b>F</b>aithfully discharge duties · <b>D</b>o right to all. Brave Upright Fair Dealings. <i>(Both oaths administered by Governor.)</i>'),
  t('<b>Term and pay</b>', '<b>No fixed term</b>; during <b>Governor’s pleasure</b> (Art 164) = only while he has <b>Assembly confidence</b>', 'majority support: Governor cannot dismiss; on losing confidence must resign or may be dismissed', '<b>Salary</b> set by State Legislature, plus MLA salary: <b>sumptuary allowance, free residence, travelling allowance, medical and other facilities</b>', w=24),
  mn('TRAM', 'CM’s perks: <b>T</b>ravelling allowance, <b>R</b>esidence free, <b>A</b>llowance sumptuary, <b>M</b>edical and other facilities. <i>(Unordered.)</i>'),
  sec('POWERS OF THE CM', 'g'),
  tb(['Relation', 'Powers'],
     ['<b>Council</b>', 'Governor appoints only persons CM recommends; allocates, reshuffles portfolios; asks a minister to resign or advises dismissal; presides; guides, coordinates, controls. <b>His resignation or death collapses whole Council</b>; another minister’s only creates a vacancy'],
     ['<b>Governor (Art 167)</b>', 'channel between Governor and Council; communicates decisions on administration and legislative proposals; furnishes information called for; submits a one-minister matter for Council reconsideration if Governor requires; advises on Advocate-General, SPSC members, State Election Commissioner'],
     ['<b>Legislature</b>', 'advises on summoning, proroguing, dissolving; can recommend dissolution any time; announces policies; keeps House informed'],
     ['<b>Executive</b>', 'supervises Secretariat headed by Chief Secretary; oversees senior appointments; leads civil service on discipline, efficiency, morale; influences PSU, Board, Commission appointments']),
  mn('C-G-L-E-O', 'Heads of CM’s powers: <b>C</b>ouncil, <b>G</b>overnor, <b>L</b>egislature, <b>E</b>xecutive, <b>O</b>ther. Chief Guides Legislature Executive Others. <i>(Handout order.)</i>'),
  tb(['Other role', 'Detail'],
     ['State Planning Board', 'Chairman'],
     ['Zonal Council', 'Vice-Chairman by rotation, 1 year at a time (Union Home Minister chairs all zonal councils)'],
     ['Inter-State Council, NITI Aayog Governing Council', 'ex-officio member (both headed by PM)'],
     ['Others', 'chief spokesperson; crisis manager-in-chief (political); hears grievances; political head of State services']),
  bx('ye', '<b>CM falls = Council falls.</b> CM resigns or dies: entire Council goes. Any other minister: only a vacancy.'),
  sec('GOVERNOR AND CM: ARTS 163, 164, 167', 'b'),
  tb(['Art', 'Rule'],
     ['<b>163</b>', 'Governor acts on aid and advice of Council under CM. <b>Two exceptions:</b> where Constitution requires discretion (e.g. CM when no majority) and special responsibilities (e.g. Sixth Schedule areas, reserving Bills). <b>Art 163(2),(3):</b> his decision on discretion is final; advice not enquired into by courts. <b>Shamsher Singh (1974):</b> his “satisfaction” = satisfaction of Council'],
     ['<b>164</b>', '(a) CM appointed by Governor; (b) other ministers on CM’s advice; (c) pleasure, in practice Assembly confidence; (d) <b>collective responsibility</b> to Assembly; (e) oaths by Governor; (f) non-member minister ceases after <b>6 consecutive months</b>. <b>Art 164(1B)</b> (91st Am.): defection-disqualified legislator also disqualified as minister'],
     ['<b>167</b>', 'CM communicates decisions and proposals; gives information; submits matters for reconsideration'],
     ['<b>Art 166</b>', 'all executive action in Governor’s name; authenticated order cannot be questioned as not made by him'],
     ['<b>Art 177</b>', 'minister may speak in either House and committees but vote only in his own House']),
  mn('A-A-C', 'Three Articles: <b>A</b>id and advice (163), <b>A</b>ppointment and tenure (164), <b>C</b>ommunication duties of CM (167): “<b>A</b>ll <b>A</b>ct <b>C</b>losely”.'),
  bx('pk', '<b>Legitimacy:</b> appointments are in the Governor’s name, political legitimacy rests with the CM. Tribal welfare minister: originally Bihar, MP, Odisha; <b>94th Am. 2006</b> freed Bihar, added Chhattisgarh and Jharkhand; may also handle SC and backward-class welfare.'),
  sec('COUNCIL OF MINISTERS: RANKS', 'r'),
  bx('bl', 'Constitution outlines principles in <b>Art 163</b> (status) and <b>Art 164</b> (appointment, tenure, responsibility, qualifications, oath, salaries); it does <b>not</b> classify ministers into ranks: tiers are <b>convention</b> (British pattern).'),
  tb(['Rank', 'Role'],
     ['<b>Chief Minister</b>', 'head; leader of majority party or coalition; others on his advice; portfolios, presides, links Governor and ministers'],
     ['<b>Cabinet Ministers</b>', 'senior; head key departments (Home, Finance, Education, Health, Agriculture, Industries); form the <b>Cabinet</b>, supreme decision-making; frame policy, introduce Bills; collectively responsible'],
     ['<b>Ministers of State</b>', 'middle; some <b>independent charge</b> (e.g. Tribal Welfare, Small Industries, Tourism), others attached to Cabinet Ministers; not in Cabinet unless invited'],
     ['<b>Deputy Ministers</b>', 'junior-most; no independent charge; attached to Cabinet Ministers; pilot Bills, answer questions; political balancing (caste, region)']),
  mn('C-C-M-D', '<b>C</b>hief Minister, <b>C</b>abinet, <b>M</b>inisters of State, <b>D</b>eputy: Chief Commands Many Deputies; “<b>C</b>ool <b>C</b>ats <b>M</b>eet <b>D</b>aily”. A Deputy CM may sit in Council (local politics); States have departments, not ministries.'),
  sec('APPOINTMENT, TENURE AND SIZE', 'g'),
  tb(['Topic', 'Rule'],
     ['<b>Appointment</b>', 'Governor appoints CM and ministers on CM’s advice; Governor has no discretion on other ministers except rare cases (hung Assembly)'],
     ['<b>Tenure</b>', 'no fixed tenure; Governor’s pleasure (Art 164) exercised on CM’s advice; no-confidence vote: whole Council resigns'],
     ['<b>Oath</b>', '<b>Art 164(3)</b> and <b>Third Schedule</b>; office and secrecy for every minister'],
     ['<b>Salary</b>', 'State Legislature (<b>Art 164(5)</b>); until then <b>Second Schedule</b>; equal to MLA plus sumptuary allowance by rank, residence, travel, medical'],
     ['<b>Collective</b>', 'Council collectively responsible; loss of majority: entire Council steps down'],
     ['<b>Individual</b>', 'CM may advise removal of a minister who loses his confidence']),
  t('<b>91st Amendment Act, 2003</b>', '<b>Ceiling:</b> not more than <b>15%</b> of Assembly strength', '<b>Floor:</b> not less than <b>12</b> including CM', '<b>Aim:</b> stop oversized ministries (appeasement), lighten exchequer', t('<b>Handout notes</b>', 'UP, West Bengal, Orissa still have disproportionately large Councils', '<b>2nd ARC:</b> no blanket 15% norm; link strength to Assembly size'), w=24),
  sec('COLLECTIVE AND INDIVIDUAL RESPONSIBILITY', 'b'),
  two([t('<b>Collective (Art 164(2))</b>', 'Council = team; one minister’s decision is the Council’s', 'no-confidence: whole ministry incl. CM resigns', 'motion against one minister = loss of confidence by all', 'stops public opposition to policy while in office', '<b>Cabinet decisions bind all ministers</b>; one who cannot defend must resign', w=18)],
      [t('<b>Individual</b>', 'each answers for his department', 'inefficiency, corruption, policy violation: CM asks resignation, else advises dismissal', 'Council that lost confidence can advise dissolution; Governor may refuse', w=18)]),
  tb(['No legal responsibility', 'Detail'],
     ['Scope', 'ministers not legally responsible for Governor’s official acts or advice under Art 163'],
     ['Britain vs India', 'Britain: ministerial <b>countersignature</b> makes ministers liable; India: none'],
     ['Result', 'cannot be prosecuted or sued for advice; accountability <b>political, not legal</b>; Governor’s acts stay valid']),
  mn('C-I-N', 'Three responsibilities: <b>C</b>ollective, <b>I</b>ndividual, <b>N</b>o legal liability: “<b>C</b>ouncil <b>I</b>s <b>N</b>ot sued”.'),
  sec('COUNCIL POWERS, CABINET, COMMITTEES', 'r'),
  tb(['Sphere', 'What it does'],
     ['<b>Executive</b>', 'implements laws; supervises police, education, health, agriculture, industries, welfare; policies; coordinates ministries'],
     ['<b>Legislative</b>', 'introduces most Bills, esp. <b>Money Bills</b> (need its prior approval); manages debates; in power only with majority'],
     ['<b>Advisory</b>', 'advises Governor except discretion: <b>Ordinance-making</b>; appointments (Advocate-General, State Election Commissioner, SPSC); dissolution on its recommendation'],
     ['<b>Financial</b>', 'prepares and presents annual budget; revenue, expenditure control; no Money Bill or demand without approval']),
  mn('LEAF', '<b>L</b>egislative, <b>E</b>xecutive, <b>A</b>dvisory, <b>F</b>inancial: the Council is the LEAF through which governance feeds. <i>(Order rearranged; unordered.)</i>'),
  t('<b>Cabinet</b>', 'smaller, <b>most powerful</b> part; cabinet-rank ministers only; supreme executive authority', 'policy, coordination, advises Governor, <b>crisis</b> management, budget, senior appointments', t('<b>Cabinet committees</b>', 'created by <b>CM</b>; number, names, composition vary', '<b>standing</b> (permanent) or <b>ad hoc</b> (temporary)', 'sometimes decide on their own; Cabinet can review and revise'), w=24),
  sec('CHIEF SECRETARY ' + P('2016'), 'b'),
  tb(['Point', 'Detail'],
     ['Cadre', 'generally senior-most <b>IAS</b> officer of State cadre; topmost executive officer, principal adviser'],
     ['<b>Appointed by</b>', '<b>Chief Minister</b>, holds office at CM’s pleasure; formally in Governor’s name'],
     ['<b>Tenure</b>', '<b>No fixed tenure</b>; continuity by convention']),
  bx('ye', '<b>PYQ 2016 trap:</b> “appointed by Governor” (false) and “fixed tenure” (false): answer <b>(d) neither</b>. Appointment is in the Governor’s name but made by the CM.'),
  tb(['Six functions', 'Detail'],
     ['Principal Adviser to CM', 'administration, policy implementation, coordinates departments'],
     ['Head of State civil services', 'executive head of Secretariat; secretaries report to him'],
     ['Secretary to the Cabinet', 'agenda, minutes, ensures implementation'],
     ['Centre-State liaison', 'main channel with Union incl. centrally sponsored schemes'],
     ['Crisis manager', 'relief, disasters, law and order crises'],
     ['Guardian of discipline', 'efficiency, integrity of civil servants; transfers and postings of senior officers']),
  mn('A-H-S-L-C-G', '“<b>A</b>ll <b>H</b>ands <b>S</b>tay <b>L</b>oyal, <b>C</b>alm, <b>G</b>uided”: Adviser, Head, Secretary to Cabinet, Liaison, Crisis manager, Guardian of discipline. <i>Role: authority and neutrality; links political executive and permanent civil service.</i>'),
  tl(('1950', 'Arts 163, 164, 167'), ('2001', 'B.R. Kapoor'), ('2003', '91st Am.: 15%, 12'), ('2006', '94th Am.'), ('2016', 'Chief Secretary PYQ')),
     ],
     recall=[('Who appoints the CM? Which Article?', 'Governor, Art 164(1); leader of majority; in hung Assembly largest party or coalition proves majority'),
             ('Non-member CM: how long?', '6 months to be elected (Art 164(4)); B.R. Kapoor (2001): no repeat appointment'),
             ('91st Amendment (2003) numbers?', 'Council max 15% of Assembly, min 12 including CM'),
             ('Four ranks of ministers?', 'CM, Cabinet Ministers, Ministers of State, Deputy Ministers (convention)'),
             ('Who is appointed by whom: Chief Secretary? (Prelims 2016)', 'By the CM, not Governor; no fixed tenure; answer (d) neither'),
             ('What happens if CM resigns or dies?', 'Entire Council falls; other minister: only a vacancy'),
             ('Collective responsibility Article?', 'Art 164(2): Council to Assembly; no legal responsibility (no countersignature)'),
             ('Sarkaria order if no majority?', 'Pre-poll alliance, largest party with support, post-poll coalition all in government, post-poll alliance with outside support'),
             ('CM roles outside the State?', 'Zonal Council vice-chair by rotation; Inter-State Council and NITI Aayog GC ex-officio member; State Planning Board chair')]),
